"""Registrar leituras e inspeção visual do lote C-02 (registro 132)."""
from pathlib import Path
from collections import Counter
import json,hashlib
A=Path(__file__).resolve().parent;R=A.parents[1]
def load(p):return json.loads(p.read_text())
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def save(n,d):(A/n).write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
m=load(A/'amostra.json');changes=load(A/'alteracoes.json');ins=load(A/'imagens-inspecionadas-primeira-prova-visual.json')['primeira_prova'];N=len(m['paginas']);assert N==10
cur={i:sha(A/f'pagina-{i:02}.png') for i in range(1,N+1)};same={i for i in cur if ins[str(i)]==cur[i]};assert same==set(range(1,11)),same
notes={1:'Abertura da ficha de acordos: proposta, tom e limites com linhas; quadro de personagens e relações.',2:'Organização, primeira situação e quadro de providências; abertura do registro de descobertas.',3:'Modelo de descobertas com quadro; exemplo do anexo com quadro preenchido.',4:'Abertura da ficha de facção, quadro de relações e exemplo da Roda das Oficinas.',5:'Fim do exemplo de facção; abertura da ficha de convivência com quadro de acontecimentos.',6:'Exemplo de Maia e Taru; abertura da ficha de avaliação; quadro Como funciona em largura cheia.',7:'Resto do quadro Como funciona, avaliação e registro, acompanhamento de Restrição.',8:'Exemplo do ajuste de montagem; abertura da ficha de projeto e entrega.',9:'Andamento, entrega, exemplo do Traje de Rina e início do registro de empréstimo.',10:'Fim do registro de empréstimo, com rótulos junto das linhas; página de fechamento curta.'}
save('revisao-final.json',{'registro':132,'pdf':m['pdf'],'pdf_sha256':m['pdf_sha256'],'passagens_textuais':[{'passagem':1,'registros':sum(c['passagem']==1 for c in changes),'escopo':'Leitura integral das seis fichas e das regras citadas, seis cópias, remissões para os capítulos novos e clareza.'},{'passagem':2,'registros':sum(c['passagem']==2 for c in changes),'escopo':'Leitura da prova completa, trechos alterados no contexto e varredura de crase, repetições e termos de produção; nenhuma alteração necessária.'}],'ajuste_de_diagramacao':'Linhas de preenchimento só nos modelos (exemplos ficam sem linhas), inclusive em listas; rótulo e linhas sempre juntos na quebra; altura de escrita nas células; quadro Como funciona em largura cheia; fichas em fluxo contínuo, como no C-01.','paginas':[{'pagina':i,'imagem':str((A/f'pagina-{i:02}.png').relative_to(R)),'imagem_sha256':cur[i],'inspecionada':True,'metodo':'Inspeção direta após o último ajuste' if False else 'Inspeção direta na primeira prova; imagem idêntica (mesmo hash)','observacao':notes[i]} for i in range(1,N+1)],'limites':['Sem leitor humano independente ou terceira leitura integral.','Espaços de fechamento no pé das páginas 3 e 7 antes de uma ficha nova e página 10 curta; reavaliar na integração (folhas soltas para impressão podem pedir uma ficha por página).','Não conclui a revisão visual global ou a comparação final do livro inteiro.']})
ranges={'s008':[1,2],'s012':[2,3],'s020':[4,5],'s028':[5,6],'s032':[6,8],'s038':[8,10]};rows=[]
for f in m['fontes']:
 counts=Counter(str(c['passagem']) for c in changes if c['fonte']==f['fonte']);rows.append({'id':f['fonte_id'],'fonte_original':f['fonte_original'],'fonte_revisada':f['fonte'],'sha256_original':f['sha256_original'],'sha256_revisado':f['sha256'],'passagem_1':'Original integral e regras pertinentes consultados.','passagem_2_paginas_da_prova':ranges[f['fonte_id']],'paginas_na_prova_final':ranges[f['fonte_id']],'registros_por_passagem':dict(counts),'estado':'duas passagens locais; conferir conjunto antes de integrar'})
save('leitura-por-caso.json',{'registro':132,'casos':rows,'limites':'Sem terceira leitura integral, teste humano ou nova simulação.'})
save('mapa-do-lote.json',{'registro':132,'lote':'C-02','casos':[f['fonte_id'] for f in m['fontes']],'pdf_parcial':m['pdf'],'paginas':N,'casos_revistos_total':59,'casos_pendentes':0,'lotes_pendentes':0,'consultas_revistas':10,'consultas_pendentes':7,'consultas_complementares_pendentes':7,'etapa_6':'em andamento','proximo_lote':'C-03','modelo_recomendado':'Claude Opus 5.5 (equivalente no plano: GPT-6.1 Sol)','esforco_recomendado':'alto','edicao_integrada':'preservada; não substituída'})
print(json.dumps({'paginas_inspecionadas':N,'registros':len(changes),'casos':6},ensure_ascii=False))
